using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
using SimplePZMapmaker.Web.Services;
using System.Text.Json;
static class NeighborhoodParcelTests {
 public static IEnumerable<(string,Action)> Cases(){
  yield return("neighborhood parcels include street access yards parking and native fences deterministically",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});var original=JsonSerializer.Serialize(p);var c=new NeighborhoodConstraints{MaximumBuildings=4,TemplateIds=["village-izba"],Variation=100};var first=NeighborhoodPlanner.Create(p,c);var second=NeighborhoodPlanner.Create(p,c);
   Check(JsonSerializer.Serialize(first.Buildings)==JsonSerializer.Serialize(second.Buildings)&&JsonSerializer.Serialize(first.Surfaces)==JsonSerializer.Serialize(second.Surfaces)&&JsonSerializer.Serialize(first.Decorations)==JsonSerializer.Serialize(second.Decorations),"Fixed seed changed parcel geometry or resources");Check(JsonSerializer.Serialize(p)==original,"Proposal modified source map");Check(first.Parcels.Count==4&&first.Parcels.All(x=>x.AccessConnected)&&first.Surfaces.Any(s=>s.Kind=="driveway")&&first.Surfaces.Any(s=>s.Kind=="parking")&&first.Surfaces.Any(s=>s.Kind=="courtyard")&&first.Decorations.Count>0,"Parcel features or street access missing");
   NeighborhoodPlanner.Apply(p,first);ProjectValidator.Validate(p);Check(p.Buildings.Count==4&&p.Decorations.Count==first.Decorations.Count&&NativeScene.ResourceIds(p).Contains("fencing_01_4"),"Parcel features did not reach the native composer");
   var game=Environment.GetEnvironmentVariable("PZMAP_GAME_PATH")??"";if(Directory.Exists(game)){var assets=new GameAssetCatalog(Path.Combine(Environment.GetEnvironmentVariable("PZMAP_WORKSPACE")??Directory.GetCurrentDirectory(),"work","parcel-catalog"),game);foreach(var d in p.Decorations)AssetRules.CheckParts(assets,d.Asset,d.Parts);AssetRules.Project(p,assets);}
  });
  yield return("all original regional templates allow bounded architectural variations without losing stairs",()=>{foreach(var t in HousingTemplates.Catalog)for(var seed=0;seed<3;seed++){var b=HousingTemplates.Create(t.Id);var shape=b.Design!.Floors.Select(f=>string.Concat(f.Cells.Select(c=>c=='.'?'.':'#'))).ToArray();var stairs=b.Design.Floors.Select(f=>f.Objects.Count(o=>o.Kind=="stairs")).ToArray();NeighborhoodVariation.Apply(b,seed);BuildingDesigner.Validate(b);Check(b.Design.Floors.Select(f=>string.Concat(f.Cells.Select(c=>c=='.'?'.':'#'))).SequenceEqual(shape)&&b.Design.Floors.Select(f=>f.Objects.Count(o=>o.Kind=="stairs")).SequenceEqual(stairs),"Variation altered room outlines or stair cores");}});
  yield return("same regional type generates distinct partitions and doors while preserving original basements and stair cores",()=>{var original=HousingTemplates.Create("village-izba");var a=NeighborhoodPlanner.Copy(original);var b=NeighborhoodPlanner.Copy(original);NeighborhoodVariation.Apply(a,11);NeighborhoodVariation.Apply(b,74);Check(a.Design!.Floors[1].Cells!=original.Design!.Floors[1].Cells&&JsonSerializer.Serialize(a.Design.Floors[1].Edges)!=JsonSerializer.Serialize(original.Design.Floors[1].Edges),"Variation changed only decoration and colors");Check(a.Design.Floors[1].Cells!=b.Design!.Floors[1].Cells,"Different seeds produced identical partitions");Check(a.Design.Floors[0].Cells==original.Design.Floors[0].Cells&&a.Kind==original.Kind&&a.Design.MinLevel==original.Design.MinLevel&&a.Design.Floors.Count==original.Design.Floors.Count&&a.Attribution.SequenceEqual(original.Attribution),"Layout variation lost type, basements, levels, or architectural references");var c=new NeighborhoodConstraints{MaximumBuildings=1,TemplateIds=["village-izba"],Variation=0};var plan=NeighborhoodPlanner.Create(MapGenerator.Generate(new(){Kind="blank"}),c);Check(plan.Buildings[0].Building.Design!.Floors.Select(f=>f.Cells).SequenceEqual(original.Design.Floors.Select(f=>f.Cells)),"Zero variation changed the original plan");});
  yield return("proposal surfaces and fence failures are atomic and manual ground remains protected",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});var plan=NeighborhoodPlanner.Create(p,new(){MaximumBuildings=2,TemplateIds=["village-izba"]});var surface=plan.Surfaces.First();TerrainEditMask.Mark(p,surface.Y*p.Width+surface.X);p.Version=6;p.Terrain[surface.Y*p.Width+surface.X]=Terrain.Sand;var before=JsonSerializer.Serialize(p);Reject(()=>NeighborhoodPlanner.Apply(p,plan));Check(JsonSerializer.Serialize(p)==before,"Rejected surface commit partially mutated project");var bad=NeighborhoodPlanner.Copy(plan);bad.Surfaces.Clear();bad.Roads.Clear();bad.Decorations.Add(new(null,new(){X=-1,Y=-1,Asset="fencing_01_4",Parts=[new(0,0,"fencing_01_4")]}));Reject(()=>NeighborhoodPlanner.Apply(p,bad));Check(JsonSerializer.Serialize(p)==before,"Rejected fence commit partially mutated project");});
  yield return("proposal expected resource owners merge atomically and conflicting owners reject",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});var plan=NeighborhoodPlanner.Create(p,new(){MaximumBuildings=1,TemplateIds=["village-izba"]});plan.AssetSources["fencing_01_4"]="game";NeighborhoodPlanner.Apply(p,plan);Check(p.AssetSources["fencing_01_4"]=="game","Expected proposal owner was not retained");var other=MapGenerator.Generate(new(){Kind="blank"});other.Version=6;other.AssetSources["fencing_01_4"]="other-provider";var before=JsonSerializer.Serialize(other);Reject(()=>NeighborhoodPlanner.Apply(other,plan));Check(JsonSerializer.Serialize(other)==before,"Owner conflict partially mutated project");});
  yield return("frontage planner preserves water painted terrain props and explicit surfaces",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.Version=6;for(var x=0;x<256;x++)p.Terrain[32*256+x]=Terrain.Road;p.Terrain[40*256+20]=Terrain.Water;p.SurfaceTiles[50*256+40]="blends_natural_01_32";TerrainEditMask.Mark(p,50*256+80);p.Terrain[50*256+80]=Terrain.Sand;p.StaticModels.Add(new(){ModelId="Base.Test",X=100,Y=50});var plan=NeighborhoodPlanner.Create(p,new(){MaximumBuildings=4,TemplateIds=["village-izba"]});NeighborhoodPlanner.Apply(p,plan);Check(p.Terrain[40*256+20]==Terrain.Water&&p.Terrain[50*256+80]==Terrain.Sand&&p.SurfaceTiles[50*256+40]=="blends_natural_01_32"&&p.StaticModels.Count==1,"Existing geography or manual content was overwritten");});
  yield return("malformed parcel proposals and oversized terrain budgets reject before commit",()=>{var plan=new NeighborhoodPlan();plan.Surfaces.Add(new(null,0,0,2048,2048,Terrain.Pavement,"parking"));Reject(()=>NeighborhoodPlanner.ValidatePlan(plan));plan.Surfaces.Clear();plan.Constraints.Variation=101;Reject(()=>NeighborhoodPlanner.ValidatePlan(plan));});
 }
 static void Check(bool value,string message){if(!value)throw new Exception(message);}static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Expected parcel validation failure");}
}
